import math, random
# Temperature + top-p (nucleus) sampling over a toy next-token distribution.
logits = {"the": 2.0, "a": 1.5, "cat": 0.3, "zebra": -1.0}
def sample(logits, temperature=1.0, top_p=0.9, rng=random.Random(42)):
    z = {t: l / temperature for t, l in logits.items()}
    m = max(z.values()); e = {t: math.exp(v - m) for t, v in z.items()}
    s = sum(e.values()); probs = sorted(((v / s, t) for t, v in e.items()), reverse=True)
    kept, cum = [], 0.0
    for p, t in probs:
        kept.append((p, t)); cum += p
        if cum >= top_p: break
    r = rng.random() * sum(p for p, _ in kept)
    for p, t in kept:
        r -= p
        if r <= 0: return t
    return kept[-1][1]
print([sample(logits, 0.7) for _ in range(8)])

import math
from collections import Counter
# Word vectors from co-occurrence counts + cosine similarity (the distributional hypothesis).
corpus = "king rules kingdom . queen rules kingdom . dog barks loudly . puppy barks loudly".split(" . ")
vocab = sorted({w for s in corpus for w in s.split()})
vec = {w: Counter() for w in vocab}
for s in corpus:
    ws = s.split()
    for w in ws:
        for c in ws:
            if c != w: vec[w][c] += 1
def cos(a, b):
    num = sum(vec[a][k]*vec[b][k] for k in vocab)
    return num / (math.sqrt(sum(v*v for v in vec[a].values())) * math.sqrt(sum(v*v for v in vec[b].values())))
print("king~queen", round(cos("king","queen"),2), " king~dog", round(cos("king","dog"),2))
assert cos("king","queen") > cos("king","dog")

import asyncio, json
from dataclasses import dataclass
# Stdlib version of "validate at the boundary" (Pydantic does this with less code).
@dataclass(frozen=True)
class Refund:
    order_id: str
    refund_usd: float
    @classmethod
    def parse(cls, raw: str) -> "Refund":
        d = json.loads(raw)
        if not isinstance(d.get("order_id"), str) or not d["order_id"].startswith("A-"):
            raise ValueError("order_id must look like 'A-123'")
        amt = d.get("refund_usd")
        if not isinstance(amt, (int, float)) or not 0 < amt <= 500:
            raise ValueError("refund_usd must be a number in (0, 500]")
        return cls(d["order_id"], float(amt))
async def fake_llm(prompt: str, attempt: int) -> str:
    await asyncio.sleep(0.01)                      # network wait
    return '{"order_id": "A-17", "refund_usd": "twenty"}' if attempt == 0 else '{"order_id": "A-17", "refund_usd": 20}'
async def get_refund(prompt: str) -> Refund:
    err = ""
    for attempt in range(3):
        raw = await asyncio.wait_for(fake_llm(prompt + err, attempt), timeout=5)
        try: return Refund.parse(raw)
        except ValueError as e: err = f"\nPrevious output invalid: {e}"
    raise RuntimeError("model never produced valid output")
