# An integration map as data + a check that every tool call is scoped, logged and uses an approved network path.
INTEGRATIONS = {
  "servicenow": {"path": "saas-tls", "auth": "oauth-client-credentials", "user": "svc_ai_triage",
                 "allow": {("incident", "read"), ("incident.work_notes", "write")}},
  "salesforce": {"path": "saas-tls", "auth": "oauth-jwt-bearer", "user": "svc_ai_lookup", "allow": {("Account", "read")},
                 "daily_limit": 100_000},
  "sap_s4": {"path": "outbound-connector", "auth": "oauth-client-credentials", "user": "SVC_AI_ORDERS",
             "allow": {("A_SalesOrder", "read")}},
}
APPROVED_PATHS = {"saas-tls", "outbound-connector", "site-to-site-vpn"}
AUDIT, USAGE = [], {}
def call(system, obj, action, user, **kw):
    cfg = INTEGRATIONS[system]
    if cfg["path"] not in APPROVED_PATHS: raise PermissionError("unapproved network path")
    if (obj, action) not in cfg["allow"]: raise PermissionError(f"{system}: {action} on {obj} not allowed")
    USAGE[system] = USAGE.get(system, 0) + 1
    if USAGE[system] > cfg.get("daily_limit", float("inf")): raise RuntimeError("API limit reached; back off")
    AUDIT.append({"on_behalf_of": user, "system": system, "as": cfg["user"], "obj": obj, "action": action, **kw})
    return f"ok: {system}.{obj}.{action}"
