def prf(rows, label):
    tp = sum(g == p == label for g, p, _ in rows); fp = sum(p == label != g for g, p, _ in rows); fn = sum(g == label != p for g, p, _ in rows)
    prec = tp / (tp + fp) if tp + fp else 0; rec = tp / (tp + fn) if tp + fn else 0
    return round(prec, 2), round(rec, 2)
